import{bindNativeCardSwipe}from './adhkar-swipe.js';
import {markDhikrActivity} from './dhikr-reminder.js';
import{showDailyDuas,stopDailyDuas}from './daily-dua.js';import{createFreeCounterStore}from './free-counter.js';import{read,write,settings}from './storage.js';import{esc,toast,modal,closeModal}from './ui.js';import{dateKey}from './prayers.js';import{createAdhkarProgressStore}from './adhkar-progress.js';import{recordingFor}from './sourced-audio.js';
const progressStore=createAdhkarProgressStore({storage:()=>localStorage,day:()=>dateKey(),locks:()=>navigator.locks});
const freeStore=createFreeCounterStore({storage:()=>localStorage,locks:()=>navigator.locks,changed:()=>window.dispatchEvent(new Event('salah:counter-changed'))});
const formatTotal=n=>n.toLocaleString('ru-RU');
const readingSizes=[16,18,20,22,24,28];
function readingSize(){const value=read('adhkar-font-size',18);return readingSizes.includes(value)?value:18}
let disposeSwipe=null;
function clearSwipe(){disposeSwipe?.();disposeSwipe=null}
let activePeriod=null,data=null,host=null,group=null,cursor=0,token=0,suppressTapUntil=0,dhikrAudio=null,dhikrAudioToken=0,renderedRoute=null;
const names={morning:'Утренние азкары',evening:'Вечерние азкары'};
function progress(g){return progressStore.progress(g)}
function save(p){const ok=progressStore.save(group,p);if(!ok)toast('Прогресс не сохранился. Проверьте доступ к хранилищу.');return ok}
function countFor(p,item){return Math.min(item.target,Math.max(0,Number(p.counts[item.id])||0))}
function completed(p,g){return data.groups[g].ids.filter(id=>countFor(p,data.items.find(i=>i.id===id))>=data.items.find(i=>i.id===id).target).length}
function rememberView(view='hub',item=null){const params=new URLSearchParams();if(group)params.set('group',group);if(view!=='hub'&&view!=='list')params.set('view',view);if(item)params.set('item',item);const hash='#adhkar'+(params.size?'?'+params.toString():'');try{if(location.hash!==hash)window.history.replaceState(window.history.state,'',hash)}catch{}renderedRoute=location.hash}
function restoreGroup(requested){if(requested==='morning'||requested==='evening')return requested;if(requested==='all'){data.groups.all={name:'Все зикры',ids:data.items.map(item=>item.id)};return requested}if(requested==='favorites'){const favorites=read('adhkar-favorites',[]);data.groups.favorites={name:'Избранное',ids:(Array.isArray(favorites)?favorites:[]).filter(id=>data.items.some(item=>item.id===id))};return requested}return null}
export function stopAdhkar(){clearSwipe();renderedRoute=null;token++;stopDailyDuas();stopDhikrAudio();document.body.classList.remove('adhkar-focus','adhkar-signature','adhkar-hybrid','adhkar-reading')}
export function adhkarHomeCard(period){if(!names[period])return '';return '<a class="home-adhkar-prompt" href="#adhkar?group='+period+'" data-adhkar-open="'+period+'">'+icon(period==='morning'?'sun':'moon-stars')+'<span>'+names[period]+'</span></a>'}
export function selectAdhkar(g){write('adhkar-selected',g)}
export async function showAdhkar(container,period=null){
 activePeriod=period;
 // Returning from another app refreshes prayer data, not the reading screen.
 if(data&&host===container&&renderedRoute===location.hash&&host.querySelector('.adhkar-shell,.dhikr-list-shell,.hybrid-heading,.lesson-complete,.daily-dua-shell')){updateAdhkarPeriod(period);return}
 stopDailyDuas();host=container;const version=++token;host.innerHTML='<section class="panel section"><h1>Азкары</h1><p class="muted">Открываем материалы…</p></section>';
 try{if(!data){const r=await fetch('./data/adhkar.json');if(!r.ok)throw Error();const d=await r.json();if(version!==token)return;data=d}if(version!==token)return;
  if(!progressStore.configure(data.items))toast('Прогресс не сохранился. Проверьте доступ к хранилищу.');
  const params=new URLSearchParams(location.hash.split('?')[1]||'');group=restoreGroup(params.get('group'));
  if(params.get('view')==='duas'){group=null;stopDhikrAudio();await showDailyDuas(host,{onBack:()=>{stopDailyDuas();hub()},onRoute:()=>{renderedRoute=location.hash}});return}
  else if(params.get('view')==='counter'){group=null;freeCounter()}
  else if(group){const index=data.groups[group].ids.indexOf(params.get('item'));if(params.get('view')==='card'&&index>=0){cursor=index;card()}else if(params.get('view')==='summary')summary();else list()}
  else hub();
 }catch{if(version!==token)return;renderedRoute=null;host.innerHTML='<section class="panel section"><h1>Материалы недоступны</h1><button class="button" id="adhkar-retry">Повторить</button></section>';host.querySelector('#adhkar-retry').onclick=()=>showAdhkar(host,activePeriod)}
}
// The adhkar cards show the surah verses without the opening basmala.
// Keep the source catalogue and the Quran reader unchanged.
function displayedVerses(item){
 const verses=item.verses||[item];
 if(!['surah112','surah113','surah114'].includes(item.id))return verses;
 return verses.map((verse,index)=>index?verse:{...verse,
  arabic:verse.arabic.replace(/^بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ\s+/u,''),
  transliteration:verse.transliteration.replace(/^Бисмилляахир-рахмаанир-рахиим\.\s+/u,'')
 });
}
function readingText(item){const text=displayedVerses(item),verses=item.verses?[{arabic:text.map(v=>v.arabic).join(' '),transliteration:text.map(v=>v.transliteration).join(' '),translation:text.map(v=>v.translation).join(' ')}]:text,recording=recordingFor('adhkar',item.id,item.arabic);return '<section class="lesson-passage dhikr-passage"><h2 class="dhikr-reading-title">'+esc(item.title)+'</h2><div class="passage-body">'+verses.map(v=>'<div class="lesson-verse"><p class="arabic dhikr-arabic" dir="rtl" lang="ar" '+(!read('adhkar-arabic',false)?'hidden':'')+'>'+esc(v.arabic)+'</p><div class="transliteration" '+(!read('adhkar-translit',true)?'hidden':'')+'><p>'+esc(v.transliteration)+'</p></div><p class="translation-label" '+(!read('adhkar-translation',true)?'hidden':'')+'>Перевод</p><p class="lesson-translation" '+(!read('adhkar-translation',true)?'hidden':'')+'>'+esc(v.translation)+'</p></div>').join('')+'<p class="lesson-author"><button class="dhikr-explanation" type="button">Пояснение смысла</button></p>'+(recording?'<div class="lesson-audio"><button class="button secondary" id="dhikr-play"><svg class="dhikr-audio-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 14v-3a8 8 0 0 1 16 0v3M4 13H3v6h4v-6H4Zm16 0h1v6h-4v-6h3Z"/></svg><span>Прослушать</span></button></div>':'')+'</div></section>'}
function card(direction=0,incoming=null){incoming?.remove();markDhikrActivity();clearSwipe();stopDhikrAudio();theme();document.body.classList.add('adhkar-reading');const g=data.groups[group],p=progress(group),item=data.items.find(i=>i.id===g.ids[cursor]),n=countFor(p,item),done=completed(p,group),size=readingSize();rememberView('card',item.id);document.body.classList.toggle('adhkar-focus',read('adhkar-focus',true));p.cursor=cursor;save(p);host.innerHTML='<div class="lesson-shell adhkar-shell" style="--reading-size:'+size+'px;--arabic-size:'+size*1.8+'px"><div class="lesson-top"><button class="text-button" id="adhkar-close">К списку</button><span>'+g.name+'</span><span>'+done+' из '+g.ids.length+' выполнено</span></div><div class="progress"><span style="width:'+done/g.ids.length*100+'%"></span></div><details class="adhkar-settings"><summary>Настройки чтения</summary><div class="adhkar-preferences"><label>Размер текста <select id="adhkar-size">'+readingSizes.map(n=>'<option '+(size===n?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label><input type="checkbox" id="adhkar-focus" '+(read('adhkar-focus',true)?'checked':'')+'> Режим чтения</label><label><input type="checkbox" id="adhkar-arabic" '+(read('adhkar-arabic',false)?'checked':'')+'> Арабский</label><label><input type="checkbox" id="adhkar-translation" '+(read('adhkar-translation',true)?'checked':'')+'> Перевод</label><label><input type="checkbox" id="adhkar-translit" '+(read('adhkar-translit',true)?'checked':'')+'> Транслитерация</label><p class="muted adhkar-transcription-guide">Транскрипция SALAH: ك — к, ق — қ; аа, ии, уу — долгий звук. Точка — остановка чтения. Для точного произношения слушайте запись.</p></div></details><span class="eyebrow">КАРТОЧКА '+(cursor+1)+' ИЗ '+g.ids.length+'</span>'+readingText(item)+'<div class="dhikr-counter-dock"><button id="adhkar-count" data-dhikr-id="'+item.id+'" class="dhikr-counter" style="--count-progress:'+n/item.target*100+'%" '+(n>=item.target?'disabled':'')+' aria-label="'+(n>=item.target?'Выполнено':'Отметить повторение')+'"><span class="count-number">'+n+'<small> / '+item.target+'</small></span><span class="count-caption">'+(n>=item.target?'✓ Выполнено':'')+'</span></button><p class="dhikr-lifetime"><span>Всего</span><strong id="adhkar-total" aria-live="polite">'+formatTotal(progressStore.total(item.id))+'</strong></p></div><div class="button-row adhkar-counter-tools" hidden><button class="text-button" id="adhkar-undo" '+(!n?'disabled':'')+'>− Одно повторение</button><button class="text-button" id="adhkar-reset">Сбросить карточку</button></div><div class="adhkar-navigation" hidden><button class="button secondary" id="adhkar-prev" '+(!cursor?'disabled':'')+'>Предыдущий</button><button class="button" id="adhkar-next">'+(cursor===g.ids.length-1?'К итогам':'Следующий зикр')+'</button></div></div>';host.querySelector('.adhkar-shell').dataset.slide=direction>0?'next':direction<0?'previous':'';if(incoming)host.querySelector('.dhikr-passage').replaceWith(incoming);bindDhikrAudio(item);readingLayout();host.querySelector('#adhkar-close').onclick=list;host.querySelector('#adhkar-size').onchange=e=>{const n=Number(e.target.value);if(!readingSizes.includes(n))return;write('adhkar-font-size',n);const shell=host.querySelector('.lesson-shell');shell.style.setProperty('--reading-size',n+'px');shell.style.setProperty('--arabic-size',n*1.8+'px');readingLayout()};host.querySelector('#adhkar-focus').onchange=e=>{write('adhkar-focus',e.target.checked);document.body.classList.toggle('adhkar-focus',e.target.checked)};host.querySelector('#adhkar-arabic').onchange=e=>{write('adhkar-arabic',e.target.checked);host.querySelectorAll('.dhikr-arabic').forEach(x=>x.hidden=!e.target.checked);readingLayout()};host.querySelector('#adhkar-translation').onchange=e=>{write('adhkar-translation',e.target.checked);host.querySelectorAll('.lesson-translation,.translation-label').forEach(x=>x.hidden=!e.target.checked);readingLayout()};host.querySelector('.dhikr-explanation').onclick=()=>hadithInfo(item);host.querySelector('.passage-body').onclick=e=>{if(Date.now()>suppressTapUntil&&!e.target.closest('summary,a,button'))hadithInfo(item)};host.querySelector('#adhkar-translit').onchange=e=>{write('adhkar-translit',e.target.checked);host.querySelectorAll('.transliteration').forEach(d=>d.hidden=!e.target.checked);readingLayout()};host.querySelector('#adhkar-count').onclick=async e=>{const button=e.currentTarget;if(button.dataset.pending)return;button.dataset.pending='true';button.disabled=true;const result=await progressStore.increment(group,item.id);delete button.dataset.pending;if(!result.ok){toast('Повторение не сохранилось. Проверьте доступ к хранилищу.');if(button===host.querySelector('#adhkar-count'))updateCount(item,progress(group));return}if(result.changed)markDhikrActivity();if(result.changed&&settings.haptic){try{navigator.vibrate?.(countFor(result.progress,item)===item.target?20:8)}catch{}}if(button===host.querySelector('#adhkar-count'))updateCount(item,result.progress,result.total)};host.querySelector('#adhkar-undo').onclick=async()=>{const result=await progressStore.undo(group,item.id);if(!result.ok){toast('Изменение не сохранилось. Проверьте доступ к хранилищу.');return}if(host.querySelector('#adhkar-count')?.dataset.dhikrId===item.id)updateCount(item,result.progress,result.total)};host.querySelector('#adhkar-reset').onclick=()=>resetConfirm(()=>{const current=progress(group);current.counts[item.id]=0;if(save(current))updateCount(item,current)});host.querySelector('#adhkar-prev').onclick=()=>{cursor--;card(-1);window.scrollTo(0,0)};bindSwipe();host.querySelector('#adhkar-next').onclick=()=>{if(cursor<g.ids.length-1){cursor++;card(1)}else summary();window.scrollTo(0,0)}}
function updateCount(item,p,total=progressStore.total(item.id)){const n=countFor(p,item),done=completed(p,group),button=host.querySelector('#adhkar-count');button.disabled=n>=item.target||!!button.dataset.pending;button.style.setProperty('--count-progress',n/item.target*100+'%');button.setAttribute('aria-label',n>=item.target?'Выполнено':'Отметить повторение');button.querySelector('.count-number').innerHTML=n+'<small> / '+item.target+'</small>';button.querySelector('.count-caption').textContent=n>=item.target?'✓ Выполнено':'';host.querySelector('#adhkar-total').textContent=formatTotal(total);host.querySelector('#adhkar-undo').disabled=!n;host.querySelector('.lesson-top span:last-child').textContent=done+' из '+data.groups[group].ids.length+' выполнено';host.querySelector('.progress span').style.width=done/data.groups[group].ids.length*100+'%'}
function summary(){clearSwipe();rememberView('summary');stopDhikrAudio();document.body.classList.remove('adhkar-reading');document.body.classList.remove('adhkar-focus');const g=data.groups[group],p=progress(group),done=completed(p,group);host.innerHTML='<section class="panel section lesson-complete"><span class="eyebrow">'+g.name+'</span><h1>'+ (done===g.ids.length?'✓ '+g.name+' завершены':'Сохранено '+done+' из '+g.ids.length)+'</h1><p class="muted">'+(done===g.ids.length?'Вы завершили выбранный набор.':'Можно вернуться к оставшимся карточкам в своём темпе.')+'</p><div class="button-row"><button id="adhkar-return" class="button">'+(done===g.ids.length?'Открыть набор':'Продолжить')+'</button><button id="adhkar-hub" class="button secondary">Все азкары</button><button id="adhkar-new" class="text-button">Начать набор заново</button></div></section>';host.querySelector('#adhkar-return').onclick=()=>{cursor=Math.max(0,g.ids.findIndex(id=>countFor(p,data.items.find(i=>i.id===id))<data.items.find(i=>i.id===id).target));card()};host.querySelector('#adhkar-hub').onclick=hub;host.querySelector('#adhkar-new').onclick=()=>resetConfirm(()=>{if(save({cursor:0,counts:{}})){cursor=0;card()}})}
function resetConfirm(action){modal('<h2>Сбросить счётчик?</h2><p class="muted">Счётчик будет сброшен.</p><div class="button-row"><button class="button" id="confirm-dhikr-reset">Сбросить</button><button class="button secondary" data-close>Отмена</button></div>');document.querySelector('#confirm-dhikr-reset').onclick=()=>{closeModal();action()}}
function freeCounter(){markDhikrActivity();clearSwipe();group=null;rememberView('counter');stopDhikrAudio();document.body.classList.remove('adhkar-reading');document.body.classList.add('adhkar-focus');const p=freeStore.snapshot();if(!p.ok){toast('Не удалось открыть сохранённый счётчик. Проверьте доступ к хранилищу.');hub();return}host.innerHTML='<div class="lesson-shell adhkar-shell"><div class="lesson-top"><button class="text-button" id="counter-close">Закрыть</button><span>Счётчик зикра</span></div><h1>В своём темпе</h1><p class="arabic" lang="ar" dir="rtl">سُبْحَانَ اللَّهِ</p><p class="muted">Субханаллах · Аллах пречист</p><p class="lesson-sources">Формула: <a href="https://sunnah.com/muslim:597a" target="_blank" rel="noopener">Муслим · 597a</a></p><div class="field"><label for="counter-target">Ваша цель</label><select id="counter-target"><option value="33">33</option><option value="100">100</option><option value="0">Без цели</option><option value="custom">Своя цель</option></select><input id="counter-custom" type="number" min="1" max="100000" step="1" aria-label="Своя цель" hidden></div><p class="muted">Цель задаёте вы. Выбранное число здесь не означает установленное религиозное предписание.</p><button class="dhikr-counter" id="free-tap"><span class="count-number" aria-live="polite">'+p.count+'</span><span class="count-caption">'+(p.target?'Цель: '+p.target:'Без цели')+'</span></button><p class="dhikr-lifetime"><span>Всего</span><strong id="free-total" aria-live="polite">'+formatTotal(p.total)+'</strong></p><div class="button-row"><button class="text-button" id="free-minus">− Одно</button><button class="button secondary" id="free-reset">Сбросить</button></div></div>';const select=host.querySelector('#counter-target'),custom=host.querySelector('#counter-custom');select.value=[0,33,100].includes(p.target)?String(p.target):'custom';custom.hidden=select.value!=='custom';custom.value=p.target||33;const account=p.account,screen=host.querySelector('#free-tap');
const current=()=>host?.querySelector('#free-tap')===screen;
const store=async(action,value)=>{const result=await freeStore.change(action,value,account);if(result.ok&&action==='increment')markDhikrActivity();if(!current())return;if(!result.ok){toast(result.reason==='account_changed'?'Аккаунт изменился. Откройте счётчик снова.':'Счёт не сохранился. Проверьте доступ к хранилищу.');updateFreeCount();return}updateFreeCount();if(action==='increment'&&settings.haptic)navigator.vibrate?.(8)};
select.onchange=()=>{custom.hidden=select.value!=='custom';if(select.value==='custom'&&!custom.checkValidity())return;return store('target',select.value==='custom'?Number(custom.value):Number(select.value))};custom.onchange=()=>{if(!custom.checkValidity()){custom.reportValidity();return}return store('target',Number(custom.value))};host.querySelector('#free-tap').onclick=()=>store('increment');host.querySelector('#free-minus').onclick=()=>store('undo');host.querySelector('#free-reset').onclick=()=>resetConfirm(()=>store('reset'));host.querySelector('#counter-close').onclick=hub;screen.dataset.account=account;updateFreeCount()}
function updateFreeCount(){const button=host?.querySelector('#free-tap');if(!button)return;const p=freeStore.snapshot();if(!p.ok)return;if(button.dataset.account!==p.account){freeCounter();return}host.querySelector('#free-tap .count-number').textContent=p.count;host.querySelector('#free-tap .count-caption').textContent=p.target?(p.count>=p.target?'✓ Цель достигнута · '+p.target:'Цель: '+p.target):'Без цели';host.querySelector('#free-total').textContent=formatTotal(p.total);if(button.dataset.target!==String(p.target)){const select=host.querySelector('#counter-target'),custom=host.querySelector('#counter-custom');select.value=[0,33,100].includes(p.target)?String(p.target):'custom';custom.hidden=select.value!=='custom';custom.value=p.target||33;button.dataset.target=String(p.target)}
}


function icon(name){return '<img class="adhkar-icon" src="./assets/'+name+'.svg" alt="">'}
function theme(){document.body.classList.add('adhkar-signature','adhkar-hybrid')}
function hybridHub(fav){return '<div class="hybrid-heading"><span class="eyebrow">ЕЖЕДНЕВНОЕ ПОМИНАНИЕ</span><h1>Азкары</h1><p>Утро и вечер. В своём темпе.</p></div><div class="hybrid-library"><button id="all-dhikr">Все азкары <span>'+data.items.length+'</span></button><button id="favorite-dhikr">Избранное <span>'+fav.length+'</span></button></div><div class="hybrid-collections">'+['morning','evening'].map(key=>{const g=data.groups[key],done=completed(progress(key),key);return '<button class="hybrid-collection '+key+(activePeriod===key?' is-current':'')+'" data-group="'+key+'"><span class="adhkar-period-badge" '+(activePeriod===key?'':'hidden')+'>Время чтения</span><span class="hybrid-emblem">'+icon(key==='morning'?'sun':'moon-stars')+'</span><span class="hybrid-collection-copy"><small>'+ (key==='morning'?'УТРО':'ВЕЧЕР')+'</small><strong>'+g.name+'</strong><span>'+g.ids.length+' азкаров'+(done?' · '+done+' завершено':'')+'</span></span><span class="hybrid-collection-progress" aria-label="'+done+' из '+g.ids.length+' завершено"><span style="width:'+done/g.ids.length*100+'%"></span></span></button>'}).join('')+'</div><button type="button" class="hybrid-collection daily-dua-entry" id="daily-dua-open"><span class="hybrid-emblem">'+icon('book')+'</span><span class="hybrid-collection-copy"><small>ДУА НА КАЖДЫЙ ДЕНЬ</small><strong>Повседневные дуа</strong><span>Дом, еда, сон и другие ситуации</span></span></button><button class="hybrid-free" id="free-counter">'+icon('list-ul')+'<span>Счётчик зикра<small>Свободное поминание</small></span></button>'}
function hub(){clearSwipe();group=null;rememberView();stopDhikrAudio();document.body.classList.remove('adhkar-reading');document.body.classList.remove('adhkar-focus');theme();const fav=read('adhkar-favorites',[]);host.innerHTML=hybridHub(fav);host.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{group=b.dataset.group;selectAdhkar(group);list()});host.querySelector('#all-dhikr').onclick=()=>{group='all';data.groups.all={name:'Все зикры',ids:data.items.map(i=>i.id)};list()};host.querySelector('#favorite-dhikr').onclick=()=>{group='favorites';data.groups.favorites={name:'Избранное',ids:read('adhkar-favorites',[]).filter(id=>data.items.some(i=>i.id===id))};list()};host.querySelector('#daily-dua-open').onclick=()=>{location.hash='adhkar?view=duas'};host.querySelector('#free-counter').onclick=freeCounter;window.scrollTo(0,0)}
function list(){clearSwipe();rememberView('list');stopDhikrAudio();document.body.classList.remove('adhkar-reading');theme();document.body.classList.add('adhkar-focus');const g=data.groups[group],p=progress(group),favorites=read('adhkar-favorites',[]),totals=progressStore.totals();host.innerHTML='<div class="dhikr-list-shell"><div class="dhikr-list-heading"><span>'+esc(g.name)+'</span><span>'+g.ids.length+' карточек</span></div><div class="dhikr-list">'+g.ids.map((id,index)=>{const item=data.items.find(i=>i.id===id),n=countFor(p,item),preview=displayedVerses(item).map(v=>v.transliteration).join(' ');return '<article style="--item-progress:'+n/item.target*100+'%" class="dhikr-list-card '+(n>=item.target?'finished':'')+'"><button class="dhikr-open" data-index="'+index+'"><span class="salah-list-number" aria-hidden="true">'+String(index+1).padStart(2,'0')+'</span><strong>'+esc(item.title)+'</strong><p>'+esc(preview)+'</p><span>'+n+' / '+item.target+' <span class="dhikr-list-total" aria-label="Всего повторений: '+formatTotal(totals[id]||0)+'">('+formatTotal(totals[id]||0)+')</span>'+(n>=item.target?' · Выполнено':'')+'</span></button><button class="dhikr-favorite" data-favorite="'+id+'" aria-label="'+(favorites.includes(id)?'Убрать из избранного':'Добавить в избранное')+'" aria-pressed="'+favorites.includes(id)+'">'+icon(favorites.includes(id)?'star-fill':'star')+'</button></article>'}).join('')+'</div>'+(g.ids.length?'<button class="button dhikr-continue" id="dhikr-continue">'+(Object.values(p.counts).some(n=>n>0)?'Продолжить чтение':'Начать по порядку')+'</button>':'<p class="muted">Нажмите звезду возле зикра, чтобы сохранить его здесь.</p>')+'<div class="dhikr-list-footer"><button class="dhikr-circle" id="dhikr-back" aria-label="Назад">'+icon('arrow-left')+'</button><button class="dhikr-circle" id="dhikr-exit" aria-label="Закрыть азкары">'+icon('x-lg')+'</button></div></div>';host.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{cursor=Number(b.dataset.index);card();window.scrollTo(0,0)});host.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const id=b.dataset.favorite,fav=read('adhkar-favorites',[]);write('adhkar-favorites',fav.includes(id)?fav.filter(x=>x!==id):[...fav,id]);if(group==='favorites')data.groups.favorites.ids=read('adhkar-favorites',[]);list()});host.querySelector('#dhikr-continue')?.addEventListener('click',()=>{cursor=Math.min(p.cursor,g.ids.length-1);card();window.scrollTo(0,0)});host.querySelector('#dhikr-back').onclick=hub;host.querySelector('#dhikr-exit').onclick=()=>{stopAdhkar();location.hash='home'};window.scrollTo(0,0)}
function hadithInfo(item){const summaries={sayyid:'Шаддад ибн Аус передал слова Пророка о главной молитве прощения. В хадисе говорится о её произнесении днём и ночью с убеждённостью в её смысле.',asbahna:'Ибн Мас‘уд передал дуа Пророка при наступлении вечера и соответствующее дуа при наступлении утра.',amsayna:'Ибн Мас‘уд передал дуа Пророка при наступлении вечера и соответствующее дуа при наступлении утра.',tasbih:'Абу Хурайра передал наставление произносить эту формулу сто раз утром и вечером.',protection:'Усман ибн Аффан передал наставление произносить эту формулу три раза утром и вечером.',surah112:'Абдуллах ибн Хубайб передал наставление читать Аль-Ихлас, Аль-Фаляк и Ан-Нас по три раза утром и вечером.',surah113:'Абдуллах ибн Хубайб передал наставление читать Аль-Ихлас, Аль-Фаляк и Ан-Нас по три раза утром и вечером.',surah114:'Абдуллах ибн Хубайб передал наставление читать Аль-Ихлас, Аль-Фаляк и Ан-Нас по три раза утром и вечером.',afiya:'Ибн Умар передал, что Пророк не оставлял это дуа утром и вечером.',bika:'Абу Хурайра передал утреннее и вечернее дуа Пророка.',bikaEvening:'В «Крепости мусульманина» приведён отдельный вечерний вариант этой молитвы.',alim:'Абу Бакр попросил научить его словам для утра и вечера. Передано дуа о защите от зла души и шайтана.',hayy:'Анас передал наставление Пророка Фатиме произносить это дуа утром и вечером.',tahlil:'В «Крепости мусульманина» приведён вариант с десятью повторениями утром и вечером и ссылки на передачи.',raditu:'В «Крепости мусульманина» приведено произнесение этой формулы трижды утром и вечером.',hasbi:'В «Крепости мусульманина» приведён вариант с семью повторениями. Оценки передач этого сообщения различаются.'};modal('<div class="modal-head"><h2>'+esc(item.title)+'</h2><button class="icon-button" data-close aria-label="Закрыть">'+icon('x-lg')+'</button></div><p class="hadith-summary">'+esc(summaries[item.id]||'Текст и порядок повторений приведены в указанном источнике.')+'</p><p class="muted">Краткое изложение содержания хадиса или примечания сборника; не дословный русский перевод.</p><p class="hadith-grade">'+esc(item.grade)+'</p>'+(item.sourceNote?'<p>'+esc(item.sourceNote)+'</p>':'')+'<p class="hadith-source">Источник: <a href="'+esc(item.source)+'" target="_blank" rel="noopener">'+esc(item.id==='sayyid'?'Сахих аль-Бухари':item.sourceLabel)+'</a></p>'+(item.additionalSource?'<p><a href="'+esc(item.additionalSource)+'" target="_blank" rel="noopener">Сопоставить оценку другой передачи</a></p>':''))}
function bindSwipe(){const shell=host.querySelector('.adhkar-shell');shell.tabIndex=0;shell.addEventListener('keydown',e=>{if(e.target.closest('button,a,input,select,textarea,summary,[contenteditable="true"]'))return;if(e.key==='ArrowLeft'){e.preventDefault();host.querySelector('#adhkar-next').click()}if(e.key==='ArrowRight'&&cursor>0){e.preventDefault();host.querySelector('#adhkar-prev').click()}});disposeSwipe=bindNativeCardSwipe(shell.querySelector('.dhikr-passage'),{onSuppress:()=>{suppressTapUntil=Date.now()+500},preview:direction=>{const ids=data.groups[group].ids,index=cursor+(direction<0?1:-1);if(index<0)return null;const wrap=document.createElement('div');wrap.innerHTML=index>=ids.length?'<section class="lesson-passage"><h2 class="dhikr-reading-title">Завершить чтение</h2><p class="lesson-translation">Посмотреть результат</p></section>':readingText(data.items.find(i=>i.id===ids[index]));return wrap.firstElementChild;},commit:(direction,incoming)=>{const ids=data.groups[group].ids;if(direction<0){if(cursor>=ids.length-1){summary()}else{cursor++;card(0,incoming)}}else if(cursor>0){cursor--;card(0,incoming)}window.scrollTo(0,0)}})}

window.addEventListener('storage',event=>{if(event.key!=='salah:adhkar-progress-v2'&&event.key!=='salah:dhikr-free'&&event.key!=='salah:counter-active-account')return;updateFreeCount();if(!group||!data)return;const button=host?.querySelector('#adhkar-count');if(!button)return;const item=data.items.find(i=>i.id===button.dataset.dhikrId);if(item)updateCount(item,progress(group))});

function stopDhikrAudio(){dhikrAudioToken++;if(dhikrAudio){dhikrAudio.onended=null;dhikrAudio.onerror=null;dhikrAudio.pause();dhikrAudio.src='';dhikrAudio=null}}
function setDhikrAudioLabel(button,label,paused=false){button.innerHTML='<svg class="dhikr-audio-icon" viewBox="0 0 24 24" aria-hidden="true">'+(paused?'<path d="M8 5v14M16 5v14"/>':'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 13H3v6h4v-6H4Zm16 0h1v6h-4v-6h3Z"/>')+'</svg><span>'+label+'</span>';}
function readingLayout(){const shell=host?.querySelector('.adhkar-shell');if(!shell)return;const selected=['adhkar-arabic','adhkar-translation','adhkar-translit'].filter(key=>host.querySelector('#'+key)?.checked).length;shell.classList.toggle('adhkar-single-text',selected===1);}
function bindDhikrAudio(item){const button=host.querySelector('#dhikr-play'),recording=recordingFor('adhkar',item.id,item.arabic);if(!button||!recording)return;button.onclick=()=>{if(dhikrAudio&&!dhikrAudio.paused){dhikrAudio.pause();setDhikrAudioLabel(button,'Продолжить');return}if(!dhikrAudio)dhikrAudio=new Audio(recording.url);const current=dhikrAudio,version=dhikrAudioToken;const failure=()=>{if(current!==dhikrAudio||version!==dhikrAudioToken)return;stopDhikrAudio();if(button.isConnected)setDhikrAudioLabel(button,'Прослушать');toast('Аудио временно недоступно. Проверьте соединение.')};current.onerror=failure;current.onended=()=>{if(current!==dhikrAudio||version!==dhikrAudioToken)return;stopDhikrAudio();if(button.isConnected)setDhikrAudioLabel(button,'Прослушать')};setDhikrAudioLabel(button,'Пауза',true);current.play().catch(failure)}}

export function updateAdhkarPeriod(period){
 activePeriod=period;
 if(!host||!data)return;
 host.querySelectorAll('[data-group]').forEach(button=>{const current=button.dataset.group===period;button.classList.toggle('is-current',current);const badge=button.querySelector('.adhkar-period-badge');if(badge)badge.hidden=!current});
 const counter=host.querySelector('#adhkar-count');
 if(counter&&!counter.dataset.pending&&data.groups[group]){const item=data.items.find(item=>item.id===counter.dataset.dhikrId);if(item)updateCount(item,progress(group))}
}

window.addEventListener('salah:counter-restored',()=>{updateFreeCount();if(!document.body.classList.contains('adhkar-signature')||!group||!data)return;const button=host?.querySelector('#adhkar-count');if(button){const item=data.items.find(i=>i.id===button.dataset.dhikrId);if(item)updateCount(item,progress(group));}else if(host?.querySelector('.dhikr-list'))list();});
